var n=`1033-goi-ga`;var t=`world-1033`;var a=`VN`;var s=`southeast-asia`;var r=4;var o=37;var g={en:`Goi Ga`,ua:`Гой га`};var d={en:`Goi Ga is a dish from Vietnam prepared with chicken breast, white cabbage, carrot, red onion. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Гой га, страва кухні країни В'єтнам, яку готують із таких продуктів: куряча грудка, білоголова капуста, морква, червона цибуля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Poach the listed ingredients in barely simmering liquid for about 22 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 22 хвилин до готовності й м’якості.`,t:[`poaching`],m:22,i:[[`chicken-breast`,550,`g`],[`water`,850,`ml`],[`ground-ginger`,20,`g`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:8,i:[[`white-cabbage`,320,`g`],[`carrot`,180,`g`],[`red-onion`,110,`g`],[`mint`,25,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`fish-sauce`,35,`ml`],[`lime-juice`,55,`ml`],[`white-granulated-sugar`,25,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut`,70,`g`],[`cilantro`,25,`g`]]}];var m={slug:n,id:t,country:`VN`,region:s,servings:4,minutes:37,title:g,text:d,steps:h};export{a as country,m as default,t as id,o as minutes,s as region,r as servings,n as slug,h as steps,d as text,g as title};